#!/usr/bin/env python3
"""Exception First production theme for the Hermes Ops dashboard.

The data template remains owned by generate_dashboard.py. This module replaces only
the legacy visual stylesheet, sanitizes local home paths, and adds deterministic
layout behavior required by the selected production design.
"""
from __future__ import annotations

import re

